 "content": "def _smallest_period(values):
    """Infer the smallest cyclic period consistent with known index/color pairs."""
    n = max(values) - min(values) + 1 if values else 1
    # The period need not exceed the span of observed indices for these puzzles.
    for period in range(1, max(2, n + 1)):
        residues = {}
        valid = True
        for index, color in values.items():
            residue = index % period
            if residue in residues and residues[residue] != color:
                valid = False
                break
            residues[residue] = color
        if valid:
            return period, residues
    return None, {}


def transform(grid):
    h, w = len(grid), len(grid[0])

    # Horizontal bands: each known row is a solid color; continue the row-color
    # sequence cyclically to fill blank rows (including a leading blank band).
    row_values = {}
    horizontal = True
    for r, row in enumerate(grid):
        colors = {v for v in row if v != 0}
        if len(colors) > 1:
            horizontal = False
            break
        if colors:
            row_values[r] = next(iter(colors))
    if horizontal and row_values and any(all(v == 0 for v in row) for row in grid):
        period, residues = _smallest_period(row_values)
        if period is not None:
            return [[residues[r % period]] * w for r in range(h)]

    # Parallel diagonal stripes are indexed by c-r. Infer their cyclic color
    # pattern from the visible stripe fragments, then extend it over the grid.
    diagonal_values = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                diagonal_values[c - r] = color
    period, residues = _smallest_period(diagonal_values)
    if period is None:
        return [row[:] for row in grid]
    return [[residues[(c - r) % period] for c in range(w)] for r in range(h)]
